mapper.select:
SELECT ts.teacher_id AS teacherId, s.id, s.subject_name, s.grade_id, g.grade_name FROM t_teacher_subject ts INNER JOIN t_as_subject s ON ts.subject_id = s.id AND s.is_valid = 1 AND s.enabled = 1 LEFT JOIN t_educl_grade g ON s.grade_id = g.id AND g.is_valid = 1 WHERE ts.teacher_id IN
#{teacherId}
AND ts.is_valid = 1 ORDER BY ts.teacher_id, g.sort_no ASC
